using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Preserve EF8 id format ("Product|123") so existing 500K documents remain readable.
        // Without this, EF9 generates bare ids ("123") and cannot find old documents.
        optionsBuilder.UseCosmos(o =>
        {
            // connection config omitted — keep your existing setup
        });
    }
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF9 renamed the discriminator from "Discriminator" to "$type".
            // Existing documents and raw SQL queries use "Discriminator",
            // so we pin the old property name for backward compatibility.
            entity.HasDiscriminator<string>("Discriminator");

            // EF9 changed the default id format from "EntityType|Key" to just "Key".
            // Existing 500K documents use "Product|123", so we must opt back in
            // to the legacy format to avoid orphaning existing data.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .HasConversion(
                      id => $"Product|{id}",
                      stored => int.Parse(stored.Replace("Product|", "")));
        });

        // HasIndex is not supported by the Cosmos provider — removed.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

